    # Read projections are part of the baseline schema.
    op.execute("CREATE VIEW unresolved_submissions AS SELECT * FROM submissions WHERE status='failed' OR target_id IS NULL")
    op.execute("CREATE VIEW failed_provider_requests AS SELECT * FROM provider_outcomes WHERE status IN ('transient_failure','permanent_failure')")
    op.execute('CREATE VIEW catalog_status AS SELECT r.id AS run_id, t.sdbid, r.provider, r.release, r.status, r.candidate_count, r.selected_source_id, r.error, r.completed_at FROM catalog_runs r JOIN targets t ON t.id=r.target_id WHERE r.is_current=1')
    op.execute('CREATE VIEW metadata_status AS SELECT r.id AS run_id, t.sdbid, r.provider, r.release, r.status, r.query_identifier, r.candidate_count, r.error, r.completed_at FROM metadata_runs r JOIN targets t ON t.id=r.target_id WHERE r.is_current=1')
    op.execute("CREATE VIEW current_simbad_metadata AS SELECT m.* FROM simbad_metadata m JOIN metadata_runs r ON r.id=m.run_id WHERE r.is_current=1 AND r.status='match'")
    op.execute('CREATE VIEW target_notes AS SELECT n.id, t.sdbid, n.actor, n.text, n.created_at FROM user_notes n JOIN targets t ON t.id=n.target_id')
