    op.execute('CREATE VIEW curated_association_history AS SELECT a.id, a.dataset, a.record_no, a.action, t.sdbid, a.actor, a.reason, a.created_at FROM curated_association_actions a LEFT JOIN targets t ON t.id=a.target_id')
    op.execute('CREATE VIEW reference_application_status AS SELECT id, provider, snapshot_sha256, status, target_count, refreshed_count, match_count, ambiguous_count, no_match_count, row_count, unmatched_row_count, created_at, completed_at FROM reference_application_runs')
    op.execute("CREATE VIEW unmatched_reference_records AS SELECT a.provider, a.snapshot_sha256, r.source_identifier, r.row_sha256 FROM reference_application_records r JOIN reference_application_runs a ON a.id=r.application_run_id WHERE r.status='unmatched'")
    op.execute("CREATE VIEW current_catalog_attributes AS SELECT a.*, t.sdbid FROM catalog_attributes a JOIN catalog_runs r ON r.id=a.run_id JOIN targets t ON t.id=a.target_id WHERE r.is_current=1 AND r.status='match'")
    op.execute("CREATE VIEW catalog_attribute_conflicts AS SELECT t.sdbid, a.key, COUNT(DISTINCT a.provider) AS provider_count, COUNT(DISTINCT COALESCE(a.value_text, CAST(a.value_float AS TEXT))) AS value_count FROM catalog_attributes a JOIN catalog_runs r ON r.id=a.run_id JOIN targets t ON t.id=a.target_id WHERE r.is_current=1 AND r.status='match' GROUP BY t.sdbid, a.key HAVING provider_count > 1 AND value_count > 1")
    op.execute('CREATE VIEW current_iras_band_selections AS SELECT f.target_id, f.status, f.normalized_separation, s.* FROM iras_detection_families f JOIN iras_band_selections s ON s.family_id=f.id WHERE f.is_current=1')
    op.execute('CREATE VIEW pending_export_targets AS SELECT t.id AS target_id, t.sdbid, COUNT(d.id) AS event_count, MIN(d.created_at) AS dirty_since FROM targets t JOIN export_dirty_targets d ON d.target_id=t.id WHERE d.exported_at IS NULL GROUP BY t.id, t.sdbid')
    op.execute('CREATE VIEW target_summary AS SELECT t.id, t.sdbid, t.ra2000_deg, t.dec2000_deg, a.source AS astrometry_source, a.proper_motion_available, a.position_bibcode, a.proper_motion_bibcode, a.parallax_bibcode, a.radial_velocity_bibcode FROM targets t LEFT JOIN astrometric_solutions a ON a.id=t.canonical_astrometry_id')
    op.execute("CREATE VIEW current_sample_memberships AS SELECT a.id AS action_id, a.sample_id, s.name AS sample_name, a.target_id, t.sdbid, a.actor, a.reason, a.created_at FROM sample_membership_actions a JOIN samples s ON s.id=a.sample_id JOIN targets t ON t.id=a.target_id WHERE a.action='add' AND a.id=(SELECT MAX(x.id) FROM sample_membership_actions x WHERE x.sample_id=a.sample_id AND x.target_id=a.target_id)")
    op.execute('CREATE VIEW sample_summary AS SELECT s.id, s.name, s.sample_date, s.note, s.created_at, s.updated_at, COUNT(m.target_id) AS member_count FROM samples s LEFT JOIN current_sample_memberships m ON m.sample_id=s.id GROUP BY s.id, s.name, s.sample_date, s.note, s.created_at, s.updated_at')
    op.execute("CREATE VIEW sample_export_summary AS SELECT r.id AS run_id, r.sample_id, s.name AS sample_name, r.output_dir, r.database_revision, r.status, r.manifest_path, r.started_at, r.completed_at, COUNT(i.id) AS target_count, SUM(CASE WHEN i.status='exported' THEN 1 ELSE 0 END) AS exported_count, SUM(CASE WHEN i.status='skipped' THEN 1 ELSE 0 END) AS skipped_count, SUM(CASE WHEN i.status='failed' THEN 1 ELSE 0 END) AS failed_count FROM sample_export_runs r JOIN samples s ON s.id=r.sample_id LEFT JOIN sample_export_items i ON i.run_id=r.id GROUP BY r.id")
